<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { productApi, type ProductListVO } from '@/api/product'
import { promotionApi, type PromotionActivity } from '@/api/promotion'

const list = ref<PromotionActivity[]>([]); const goods = ref<ProductListVO[]>([]); const loading = ref(false); const dialog = ref(false); const editingId = ref<number | null>(null)
const empty = (): PromotionActivity => ({ name: '', activityType: 'FULL_REDUCTION', priority: 0, status: 0, startAt: '', endAt: '', scopeType: 0, stackNewUserCoupon: 0, stackRepurchaseCoupon: 0, showRecommendations: 1, budgetAmount: null, maxOrderCount: null, productIds: [], categoryIds: [], excludedProductIds: [], recommendProductIds: [], thresholds: [{ thresholdAmount: 199, reductionAmount: 20 }] })
const form = reactive<PromotionActivity>(empty())
function ids(value: string) { return value.split(',').map(v => Number(v.trim())).filter(v => Number.isInteger(v) && v > 0) }
function idText(value?: number[]) { return (value || []).join(',') }
async function load() { loading.value = true; try { const [activities, productPage] = await Promise.all([promotionApi.list(), productApi.page({ page: 1, size: 200, status: 1, auditStatus: 1 })]); list.value = activities || []; goods.value = productPage?.list || [] } finally { loading.value = false } }
function open(item?: any) { Object.assign(form, empty(), item ? JSON.parse(JSON.stringify(item)) : {}); editingId.value = item?.id || null; dialog.value = true }
function addTier() { form.thresholds.push({ thresholdAmount: 0, reductionAmount: form.activityType === 'FULL_REDUCTION' ? 0 : undefined, discountRate: form.activityType === 'FULL_DISCOUNT' ? 9 : undefined }) }
function removeTier(index: number) { if (form.thresholds.length > 1) form.thresholds.splice(index, 1) }
async function save() { if (!form.name || !form.startAt || !form.endAt || !form.thresholds.length) return ElMessage.warning('请完整填写活动名称、时间和阶梯'); if (new Date(form.endAt) <= new Date(form.startAt)) return ElMessage.warning('结束时间必须晚于开始时间'); const data = JSON.parse(JSON.stringify(form)); const { id, reservedBudget, reservedOrderCount, paidBudget, paidOrderCount, ...payload } = data; payload.thresholds = payload.thresholds.map((t: any) => ({ ...t, reductionAmount: payload.activityType === 'FULL_REDUCTION' ? t.reductionAmount : null, discountRate: payload.activityType === 'FULL_DISCOUNT' ? t.discountRate : null, discountCap: payload.activityType === 'FULL_DISCOUNT' ? t.discountCap : null })); if (editingId.value) await promotionApi.update(editingId.value, payload); else await promotionApi.create(payload); ElMessage.success('活动已保存'); dialog.value = false; load() }
async function toggle(item: any, status: number) { if (status === 0) await ElMessageBox.confirm(`停用“${item.name}”后，新订单将不再享受该活动，已创建订单不受影响。`, '确认停用', { type: 'warning' }); await promotionApi.status(item.id, status); ElMessage.success(status === 1 ? '已启用' : '已停用'); load() }
onMounted(load)
</script>
<template>
  <div class="page"><div class="page-header"><div><span class="page-kicker">FULL REDUCTION / DISCOUNT</span><h1 class="page-title">满减满折</h1><p class="page-desc">同一时段可设置多个活动，优先级高的可用活动优先命中；待支付订单只预占额度，支付成功才计入核销。</p></div><el-button type="primary" @click="open()">新建活动</el-button></div>
  <el-alert title="启用前请先在「营销活动」开启满减满折能力；关闭能力将隐藏前台入口并拒绝新预览/下单。" type="warning" :closable="false" show-icon class="tip"/>
  <el-table :data="list" v-loading="loading" class="table"><el-table-column prop="name" label="活动名称" min-width="160"/><el-table-column label="类型" width="105"><template #default="{row}">{{row.activityType === 'FULL_REDUCTION' ? '满减' : '满折'}}</template></el-table-column><el-table-column prop="priority" label="优先级" width="90"/><el-table-column label="时间" min-width="260"><template #default="{row}">{{row.startAt}} 至 {{row.endAt}}</template></el-table-column><el-table-column label="额度 / 订单" min-width="180"><template #default="{row}">已核销 ¥{{row.paidBudget || 0}} / ¥{{row.budgetAmount || '不限'}}<br/>订单 {{row.paidOrderCount || 0}} / {{row.maxOrderCount || '不限'}}（预占 {{row.reservedOrderCount || 0}}）</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status === 1 ? 'success' : 'info'">{{row.status === 1 ? '已启用' : row.status === 0 ? '草稿' : '已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="220" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button v-if="row.status !== 1" link type="success" @click="toggle(row,1)">启用</el-button><el-button v-else link type="danger" @click="toggle(row,2)">停用</el-button></template></el-table-column></el-table>
  <el-dialog v-model="dialog" :title="editingId ? '编辑活动' : '新建活动'" width="760px" destroy-on-close><el-form label-width="120px"><el-form-item label="活动名称"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="活动类型"><el-radio-group v-model="form.activityType"><el-radio value="FULL_REDUCTION">满减</el-radio><el-radio value="FULL_DISCOUNT">满折</el-radio></el-radio-group><el-input-number v-model="form.priority" :min="0" class="priority"/><span class="hint">数值越大，优先级越高</span></el-form-item><el-form-item label="活动时间"><el-date-picker v-model="form.startAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/><span class="to">至</span><el-date-picker v-model="form.endAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="适用范围"><el-select v-model="form.scopeType"><el-option :value="0" label="全店商品"/><el-option :value="1" label="指定分类"/><el-option :value="2" label="指定商品"/></el-select></el-form-item><el-form-item v-if="form.scopeType === 1" label="分类 ID"><el-input :model-value="idText(form.categoryIds)" @update:model-value="form.categoryIds=ids($event)" placeholder="多个分类 ID 用逗号分隔"/></el-form-item><el-form-item v-if="form.scopeType === 2" label="商品 ID"><el-input :model-value="idText(form.productIds)" @update:model-value="form.productIds=ids($event)" placeholder="多个商品 ID 用逗号分隔"/></el-form-item><el-form-item label="排除商品 ID"><el-input :model-value="idText(form.excludedProductIds)" @update:model-value="form.excludedProductIds=ids($event)" placeholder="可选，多个 ID 用逗号分隔"/></el-form-item><el-form-item label="优惠阶梯"><div class="tiers"><div v-for="(tier,index) in form.thresholds" :key="index" class="tier"><span>满</span><el-input-number v-model="tier.thresholdAmount" :min="0.01" :precision="2"/><span>{{form.activityType === 'FULL_REDUCTION' ? '减' : '享'}}</span><el-input-number v-if="form.activityType === 'FULL_REDUCTION'" v-model="tier.reductionAmount" :min="0.01" :precision="2"/><el-input-number v-else v-model="tier.discountRate" :min="0.01" :max="10" :precision="2"/><template v-if="form.activityType === 'FULL_DISCOUNT'"><span>折，最高优惠</span><el-input-number v-model="tier.discountCap" :min="0.01" :precision="2" placeholder="可不填"/><span>元</span></template><el-button link type="danger" @click="removeTier(index)">删除</el-button></div><el-button link type="primary" @click="addTier">+ 添加阶梯</el-button></div></el-form-item><el-form-item label="预算 / 订单上限"><el-input-number v-model="form.budgetAmount" :min="0.01" :precision="2" placeholder="预算（可不填）" class="limit-input"/><el-input-number v-model="form.maxOrderCount" :min="1" placeholder="订单数（可不填）" class="limit-input"/></el-form-item><el-form-item label="与券叠加"><el-checkbox v-model="form.stackNewUserCoupon" :true-value="1" :false-value="0">新人券</el-checkbox><el-checkbox v-model="form.stackRepurchaseCoupon" :true-value="1" :false-value="0">复购券</el-checkbox></el-form-item><el-form-item label="凑单推荐"><el-checkbox v-model="form.showRecommendations" :true-value="1" :false-value="0">展示推荐</el-checkbox><el-select v-model="form.recommendProductIds" multiple filterable clearable :disabled="form.showRecommendations !== 1" placeholder="搜索并选择凑单商品" class="recommend-select"><el-option v-for="product in goods" :key="product.id" :value="product.id" :label="`${product.name} · ID ${product.id}`"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div>
</template>
<style scoped>.tip{margin-bottom:18px}.table{width:100%}.priority{margin-left:24px;width:110px}.hint{margin-left:10px;color:var(--shop-muted);font-size:12px}.to{margin:0 10px}.tiers{width:100%}.tier{display:flex;align-items:center;gap:8px;margin-bottom:10px}.tier .el-input-number{width:138px}.limit-input{width:180px;margin-right:12px}.el-form-item :deep(.el-checkbox){margin-right:18px}.el-form-item :deep(.el-input){max-width:520px}.recommend-select{width:520px;max-width:100%}:deep(.el-dialog){width:min(880px,calc(100vw - 32px))!important}</style>
